"""Behavioral unit tests for tenant_metric_label_values_bulk custom run.

Covers the map-shaped GET path (must not go through ``.first()``) and
idempotent replace. Not autogenerated — lives beside the smoke structure tests.
"""

import sys
from pathlib import Path
from unittest.mock import MagicMock

# Collections root so the real ``ansible_collections`` namespace resolves.
collection_root = Path(__file__).parent.parent.parent.parent.parent
sys.path.insert(0, str(collection_root.parent.parent.parent))

from ansible_collections.vastdata.vms.plugins.module_utils.vast.errors import (  # noqa: E402
    VastAPIError,
)
from ansible_collections.vastdata.vms.plugins.modules.tenant_metric_label_values_bulk import (  # noqa: E402
    TenantMetricLabelValuesBulk,
)


class _FakeApiBase:
    def __init__(self, mapping):
        self._mapping = mapping
        self.get_calls = 0
        self.post_payloads = []

    def get(self, **params):
        # Mirror _APIPath.get(): dict responses are wrapped as a one-element list.
        self.get_calls += 1
        if self._mapping is None:
            return []
        return [dict(self._mapping)]

    def post(self, **payload):
        self.post_payloads.append(dict(payload))
        self._mapping = dict(payload)
        return dict(payload)

    def first(self, **params):
        raise AssertionError("bulk map run must not call first() on a dict response")


def _exit_json(**kwargs):
    raise SystemExit(kwargs)


def _fail_json(**kwargs):
    raise SystemExit(kwargs)


def _make_resource(mapping, values=None, check_mode=False):
    fake = _FakeApiBase(mapping)
    cls = type(
        "TenantMetricLabelValuesBulk",
        (TenantMetricLabelValuesBulk,),
        {"_api_base": property(lambda self: fake)},
    )
    res = cls.__new__(cls)
    res.module = MagicMock()
    res.module.exit_json.side_effect = _exit_json
    res.module.fail_json.side_effect = _fail_json
    res.params = {"tenant_id": 1, "values": values}
    res.check_mode = check_mode
    res._fake = fake
    res.run = TenantMetricLabelValuesBulk.run.__get__(res, cls)
    return res


def _run(res):
    try:
        res.run()
    except SystemExit as exc:
        return exc.args[0]
    raise AssertionError("run() did not exit via exit_json/fail_json")


class TestBulkMapRun:
    def test_omit_values_reads_whole_map(self):
        current = {"customer": "acme", "region": "us-west"}
        res = _make_resource(current, values=None)
        kwargs = _run(res)
        assert kwargs["changed"] is False
        assert kwargs["tenant_metric_label_values_bulk"] == current
        assert res._fake.get_calls == 1
        assert res._fake.post_payloads == []

    def test_identical_map_is_idempotent(self):
        current = {"customer": "acme"}
        res = _make_resource(current, values={"customer": "acme"})
        kwargs = _run(res)
        assert kwargs["changed"] is False
        assert res._fake.post_payloads == []

    def test_string_equivalent_map_is_idempotent(self):
        res = _make_resource({"quota": "100"}, values={"quota": 100})
        kwargs = _run(res)
        assert kwargs["changed"] is False
        assert res._fake.post_payloads == []

    def test_replace_posts_whole_map(self):
        res = _make_resource({"customer": "old"}, values={"customer": "new", "region": "eu"})
        kwargs = _run(res)
        assert kwargs["changed"] is True
        assert kwargs["tenant_metric_label_values_bulk"] == {"customer": "new", "region": "eu"}
        assert res._fake.post_payloads == [{"customer": "new", "region": "eu"}]
        assert kwargs["diff"]["before"] == {"customer": "old"}
        assert kwargs["diff"]["after"] == {"customer": "new", "region": "eu"}

    def test_replace_coerces_keys_and_values_to_strings(self):
        res = _make_resource({"quota": "old"}, values={7: 100})
        kwargs = _run(res)
        assert kwargs["changed"] is True
        assert kwargs["tenant_metric_label_values_bulk"] == {"7": "100"}
        assert res._fake.post_payloads == [{"7": "100"}]

    def test_check_mode_does_not_post(self):
        res = _make_resource({"customer": "old"}, values={"customer": "new"}, check_mode=True)
        kwargs = _run(res)
        assert kwargs["changed"] is True
        assert res._fake.post_payloads == []

    def test_empty_map_read_is_safe(self):
        res = _make_resource({}, values=None)
        kwargs = _run(res)
        assert kwargs["changed"] is False
        assert kwargs["tenant_metric_label_values_bulk"] == {}

    def test_none_get_read_is_safe(self):
        res = _make_resource(None, values=None)
        kwargs = _run(res)
        assert kwargs["changed"] is False
        assert kwargs["tenant_metric_label_values_bulk"] == {}

    def test_get_vast_api_error_fails_json(self):
        res = _make_resource({}, values=None)

        def _boom(**params):
            raise VastAPIError("boom")

        res._fake.get = _boom
        kwargs = _run(res)
        assert "Failed to read metric_label_values/bulk" in kwargs["msg"]
        assert "boom" in kwargs["msg"]
